    pub fn draw(&mut self, scene: &Scene) {
        let layer = self.layer.clone();
        let viewport_size = layer.drawable_size();
        let viewport_size: Size<DevicePixels> = size(
            (viewport_size.width.ceil() as i32).into(),
            (viewport_size.height.ceil() as i32).into(),
        );
        // gpuijs patch: a backdrop blur reads the drawable; other frames keep it write-only, which
        // lets the GPU skip work.
        let readable = !scene.backdrops.is_empty();
        if layer.framebuffer_only() == readable {
            layer.set_framebuffer_only(!readable);
        }
        let drawable = if let Some(drawable) =
            crate::profile::time("drawable wait", || layer.next_drawable())
        {
            drawable
        } else {
            log::error!(
                "failed to retrieve next drawable, drawable size: {:?}",
                viewport_size
            );
            return;
        };

        loop {
            let mut instance_buffer = self.instance_buffer_pool.lock().acquire(&self.device);

            // gpuijs patch: numbered for `profile::frame_completed_at`.
            let frame = crate::profile::frame_submitted();
            let command_buffer = crate::profile::time("encode", || {
                self.draw_primitives(scene, &mut instance_buffer, drawable, viewport_size)
            });

            match command_buffer {
                Ok(command_buffer) => {
                    let instance_buffer_pool = self.instance_buffer_pool.clone();
                    let instance_buffer = Cell::new(Some(instance_buffer));
                    let block =
                        ConcreteBlock::new(move |command_buffer: &metal::CommandBufferRef| {
                            // gpuijs patch: the GPU's time on the frame, with `GPUIJS_PROFILE` set.
                            if crate::profile::enabled() {
                                let (start, end): (f64, f64) = unsafe {
                                    (
                                        msg_send![command_buffer, GPUStartTime],
                                        msg_send![command_buffer, GPUEndTime],
                                    )
                                };
                                crate::profile::gpu_frame(end - start);
                            }
                            crate::profile::frame_completed(frame);
                            if let Some(instance_buffer) = instance_buffer.take() {
                                instance_buffer_pool.lock().release(instance_buffer);
                            }
                        });
                    let block = block.copy();
                    command_buffer.add_completed_handler(&block);

                    if self.presents_with_transaction {
                        command_buffer.commit();
                        command_buffer.wait_until_scheduled();
                        drawable.present();
                    } else {
                        command_buffer.present_drawable(drawable);
                        command_buffer.commit();
                    }
                    return;
                }
                Err(err) => {
                    log::error!(
                        "failed to render: {}. retrying with larger instance buffer size",
                        err
                    );
                    let mut instance_buffer_pool = self.instance_buffer_pool.lock();
                    let buffer_size = instance_buffer_pool.buffer_size;
                    if buffer_size >= 256 * 1024 * 1024 {
                        log::error!("instance buffer size grew too large: {}", buffer_size);
                        break;
                    }
                    instance_buffer_pool.reset(buffer_size * 2);
                    log::info!(
                        "increased instance buffer size to {}",
                        instance_buffer_pool.buffer_size
                    );
                }
            }
        }
    }

    fn draw_primitives(
        &mut self,
        scene: &Scene,
        instance_buffer: &mut InstanceBuffer,
        drawable: &metal::MetalDrawableRef,
        viewport_size: Size<DevicePixels>,
    ) -> Result<metal::CommandBuffer> {
        let command_queue = self.command_queue.clone();
        let command_buffer = command_queue.new_command_buffer();
        let alpha = if self.layer.is_opaque() { 1. } else { 0. };
        let mut instance_offset = 0;

        let mut command_encoder = new_command_encoder(
            command_buffer,
            drawable.texture(),
            viewport_size,
            |color_attachment| {
                color_attachment.set_load_action(metal::MTLLoadAction::Clear);
                color_attachment.set_clear_color(metal::MTLClearColor::new(0., 0., 0., alpha));
            },
        );

        // gpuijs patch: a group's batches draw into the offscreen texture of its nesting level,
        // which is composited into the enclosing group's texture (or the drawable) with the
        // group's effect when the group's batches end. Groups nested deeper draw unaffected.
        let group_textures = self.group_textures.clone();
        let level = |depth: usize| -> &metal::TextureRef {
            match depth.checked_sub(1) {
                Some(d) => &group_textures[d],
                None => drawable.texture(),
            }
        };
        let mut groups: Vec<(usize, GroupEffect)> = Vec::new();
        let mut target: &metal::TextureRef = drawable.texture();

        // gpuijs patch: backdrops are drawn between batches, in draw order: each blurs what
        // its group has drawn so far.
        enum Step<'a> {
            Backdrop(&'a crate::scene::Backdrop),
            Batch(PrimitiveBatch<'a>),
        }
        let mut backdrops = scene.backdrops.iter().peekable();
        let mut batches = scene.batches().peekable();
        loop {
            let step = match (backdrops.peek(), batches.peek()) {
                (Some(backdrop), Some(batch)) if backdrop.order <= batch.order() => {
                    Step::Backdrop(backdrops.next().unwrap_or_else(|| unreachable!()))
                }
                (_, Some(_)) => Step::Batch(batches.next().unwrap_or_else(|| unreachable!())),
                (Some(_), None) => {
                    Step::Backdrop(backdrops.next().unwrap_or_else(|| unreachable!()))
                }
                (None, None) => break,
            };
            let order = match &step {
                Step::Backdrop(backdrop) => backdrop.order,
                Step::Batch(batch) => batch.order(),
            };
            let mut next: Vec<(usize, GroupEffect)> = scene.groups_at(order).collect();
            next.truncate(group_textures.len());
            if next.iter().map(|g| g.0).ne(groups.iter().map(|g| g.0)) {
                command_encoder.end_encoding();
                let common = groups
                    .iter()
                    .zip(&next)
                    .take_while(|(a, b)| a.0 == b.0)
                    .count();
                while groups.len() > common {
                    let (_, effect) = groups.pop().unwrap_or_else(|| unreachable!());
                    let depth = groups.len();
                    self.composite_group(
                        effect,
                        level(depth + 1),
                        viewport_size,
                        command_buffer,
                        level(depth),
                    );
                }
                // Every level opened here starts out empty.
                let opened = next.len() > groups.len();
                for depth in groups.len() + 1..next.len() {
                    new_command_encoder(command_buffer, level(depth), viewport_size, clear)
                        .end_encoding();
                }
                groups = next;
                target = level(groups.len());
                command_encoder =
                    new_command_encoder(command_buffer, target, viewport_size, |attachment| {
                        match opened {
                            true => clear(attachment),
                            false => attachment.set_load_action(metal::MTLLoadAction::Load),
                        }
                    });
            }
            let batch = match step {
                Step::Batch(batch) => batch,
                Step::Backdrop(backdrop) => {
                    command_encoder.end_encoding();
                    self.draw_backdrop(backdrop, target, viewport_size, command_buffer);
                    command_encoder =
                        new_command_encoder(command_buffer, target, viewport_size, |attachment| {
                            attachment.set_load_action(metal::MTLLoadAction::Load);
                        });
                    continue;
                }
            };
            let ok = match batch {
                PrimitiveBatch::Shadows(shadows) => self.draw_shadows(
                    shadows,
                    instance_buffer,
                    &mut instance_offset,
                    viewport_size,
                    command_encoder,
                ),
                PrimitiveBatch::Quads(quads) => self.draw_quads(
                    quads,
                    instance_buffer,
                    &mut instance_offset,
                    viewport_size,
                    command_encoder,
                ),
                PrimitiveBatch::Paths(paths) => {
                    command_encoder.end_encoding();

                    let did_draw = self.draw_paths_to_intermediate(
                        paths,
                        instance_buffer,
                        &mut instance_offset,
                        viewport_size,
                        command_buffer,
                    );

                    command_encoder = new_command_encoder(
                        command_buffer,
                        target,
                        viewport_size,
                        |color_attachment| {
                            color_attachment.set_load_action(metal::MTLLoadAction::Load);
                        },
                    );

                    if did_draw {
                        self.draw_paths_from_intermediate(
                            paths,
                            instance_buffer,
                            &mut instance_offset,
                            viewport_size,
                            command_encoder,
                        )
                    } else {
                        false
                    }
                }
                PrimitiveBatch::Underlines(underlines) => self.draw_underlines(
                    underlines,
                    instance_buffer,
                    &mut instance_offset,
                    viewport_size,
                    command_encoder,
                ),
                PrimitiveBatch::MonochromeSprites {
                    texture_id,
                    sprites,
                } => self.draw_monochrome_sprites(
                    texture_id,
                    sprites,
                    instance_buffer,
                    &mut instance_offset,
                    viewport_size,
                    command_encoder,
                ),
                PrimitiveBatch::PolychromeSprites {
                    texture_id,
                    sprites,
                } => self.draw_polychrome_sprites(
                    texture_id,
                    sprites,
                    instance_buffer,
                    &mut instance_offset,
                    viewport_size,
                    command_encoder,
                ),
                PrimitiveBatch::Surfaces(surfaces) => self.draw_surfaces(
                    surfaces,
                    instance_buffer,
                    &mut instance_offset,
                    viewport_size,
                    command_encoder,
                ),
            };
            if !ok {
                command_encoder.end_encoding();
                anyhow::bail!(
                    "scene too large: {} paths, {} shadows, {} quads, {} underlines, {} mono, {} poly, {} surfaces",
                    scene.paths.len(),
                    scene.shadows.len(),
                    scene.quads.len(),
                    scene.underlines.len(),
                    scene.monochrome_sprites.len(),
                    scene.polychrome_sprites.len(),
                    scene.surfaces.len(),
                );
            }
        }

        command_encoder.end_encoding();
        while let Some((_, effect)) = groups.pop() {
            let depth = groups.len();
            self.composite_group(
                effect,
                level(depth + 1),
                viewport_size,
                command_buffer,
                level(depth),
            );
        }

        instance_buffer.metal_buffer.did_modify_range(NSRange {
            location: 0,
            length: instance_offset as NSUInteger,
        });
        Ok(command_buffer.to_owned())
    }

    /// gpuijs patch: CSS `backdrop-filter: blur()`: replaces `backdrop`'s area of `target` with
    /// itself blurred, mixed in at the backdrop's opacity. Its cost barely grows with the radius:
    /// the area is halved until a few texels of blur remain (each halving one bilinear tap per
    /// pixel), blurred there in two 1-D passes, and stretched back over the box.
    fn draw_backdrop(
        &self,
        backdrop: &crate::scene::Backdrop,
        target: &metal::TextureRef,
        viewport_size: Size<DevicePixels>,
        command_buffer: &metal::CommandBufferRef,
    ) {
        let [scratch_a, scratch_b] = self.backdrop_textures.as_slice() else {
            return;
        };
        let (width, height) = (viewport_size.width.0 as f32, viewport_size.height.0 as f32);
        let area = backdrop.bounds.intersect(&backdrop.content_mask.bounds);
        let (x0, y0) = (
            area.origin.x.0.floor().max(0.),
            area.origin.y.0.floor().max(0.),
        );
        let x1 = (area.origin.x.0 + area.size.width.0).ceil().min(width);
        let y1 = (area.origin.y.0 + area.size.height.0).ceil().min(height);
        let sigma = backdrop.sigma.0;
        if x1 <= x0 || y1 <= y0 || sigma <= 0. {
            return;
        }
        let levels = backdrop_levels(sigma);
        let scratch_size = [scratch_a.width() as f32, scratch_a.height() as f32];
        // A pass drawing `dst` (origin, size) of a `target_size` target from `src` of a source.
        let pass =
            |dst: [f32; 4], target_size, src: [f32; 4], src_texture_size, scale| BackdropPass {
                dst_origin: [dst[0], dst[1]],
                dst_size: [dst[2], dst[3]],
                target_size,
                src_origin: [src[0], src[1]],
                src_size: [src[2], src[3]],
                src_texture_size,
                scale: [scale, scale],
                ..BackdropPass::default()
            };
        let run = |pipeline: &metal::RenderPipelineStateRef,
                   pass: &BackdropPass,
                   source: &metal::TextureRef,
                   dest: &metal::TextureRef,
                   composite: bool| {
            let dest_size = size(
                DevicePixels(dest.width() as i32),
                DevicePixels(dest.height() as i32),
            );
            let encoder = new_command_encoder(command_buffer, dest, dest_size, |attachment| {
                attachment.set_load_action(match composite {
                    true => metal::MTLLoadAction::Load,
                    // Passes read only the rectangles they wrote.
                    false => metal::MTLLoadAction::DontCare,
                });
            });
            encoder.set_render_pipeline_state(pipeline);
            encoder.set_vertex_buffer(0, Some(&self.unit_vertices), 0);
            let bytes = mem::size_of::<BackdropPass>() as u64;
            let pass = pass as *const BackdropPass as *const c_void;
            encoder.set_vertex_bytes(1, bytes, pass);
            encoder.set_fragment_bytes(1, bytes, pass);
            encoder.set_fragment_texture(0, Some(source));
            if composite {
                let opacity = backdrop.opacity;
                encoder.set_blend_color(opacity, opacity, opacity, opacity);
            }
            encoder.draw_primitives(metal::MTLPrimitiveType::Triangle, 0, 6);
            encoder.end_encoding();
        };

        // Halve the area `levels` times, ping-ponging between the scratch textures.
        let scratch: [&metal::TextureRef; 2] = [scratch_a, scratch_b];
        let mut source: &metal::TextureRef = target;
        let mut src = [x0, y0, x1 - x0, y1 - y0];
        let mut src_texture_size = [width, height];
        for level in 0..levels {
            let dest = scratch[level % 2];
            let dst = [0., 0., (src[2] / 2.).ceil(), (src[3] / 2.).ceil()];
            let p = pass(dst, scratch_size, src, src_texture_size, 2.);
            run(
                &self.backdrop_downsample_pipeline_state,
                &p,
                source,
                dest,
                false,
            );
            source = dest;
            src = dst;
            src_texture_size = scratch_size;
        }
        // The rest of the blur, along x into the other texture and along y back.
        let (low, other) = (scratch[(levels - 1) % 2], scratch[levels % 2]);
        let mut p = pass(src, scratch_size, src, scratch_size, 1.);
        p.sigma = backdrop_sigma(sigma, levels);
        p.direction = [1., 0.];
        run(&self.backdrop_blur_pipeline_state, &p, low, other, false);
        p.direction = [0., 1.];
        run(&self.backdrop_blur_pipeline_state, &p, other, low, false);

        // Back over the box at full size, inside its corners: the area's top-left pixel corner
        // is the first low texel's.
        let factor = (1usize << levels) as f32;
        let mut p = pass(
            [x0, y0, x1 - x0, y1 - y0],
            [width, height],
            src,
            scratch_size,
            1. / factor,
        );
        p.bounds_origin = [backdrop.bounds.origin.x.0, backdrop.bounds.origin.y.0];
        p.bounds_size = [backdrop.bounds.size.width.0, backdrop.bounds.size.height.0];
        let r = &backdrop.corner_radii;
        p.radii_top = [r.top_left.0, r.top_right.0];
        p.radii_bottom = [r.bottom_right.0, r.bottom_left.0];
        run(
            &self.backdrop_composite_pipeline_state,
            &p,
            low,
            target,
            true,
        );
    }

    /// gpuijs patch: blends a finished group's `pixels` onto `target` at its opacity, through its
    /// transform.
    fn composite_group(
        &self,
        effect: GroupEffect,
        pixels: &metal::TextureRef,
        viewport_size: Size<DevicePixels>,
        command_buffer: &metal::CommandBufferRef,
        target: &metal::TextureRef,
    ) {
        let (filter, area) = effect.filter.unwrap_or((crate::Filter::IDENTITY, Bounds::default()));
        // CSS `filter: blur()`: the group's pixels around the box blurred in place, as a backdrop
        // under its box is.
        if filter.blur > crate::Pixels::ZERO {
            let viewport = Bounds::new(
                Point::default(),
                viewport_size.map(|d| ScaledPixels(d.0 as f32)),
            );
            let blur = crate::scene::Backdrop {
                order: 0,
                bounds: area,
                content_mask: ContentMask { bounds: viewport, ..Default::default() },
                corner_radii: crate::Corners::default(),
                sigma: ScaledPixels(filter.blur.0),
                opacity: 1.,
            };
            self.draw_backdrop(&blur, pixels, viewport_size, command_buffer);
        }
        let [r, g, b, a] = filter.matrix;
        let composite = GroupComposite {
            rows: [r, g, b, a].map(|row| [row[0], row[1], row[2], row[3]]),
            offset: [r[4], g[4], b[4], a[4]],
            opacity: effect.opacity,
            pad: [0.; 3],
        };
        let command_encoder =
            new_command_encoder(command_buffer, target, viewport_size, |attachment| {
                attachment.set_load_action(metal::MTLLoadAction::Load);
            });
        command_encoder.set_render_pipeline_state(&self.group_sprites_pipeline_state);
        command_encoder.set_vertex_buffer(
            SpriteInputIndex::Vertices as u64,
            Some(&self.unit_vertices),
            0,
        );
        command_encoder.set_vertex_bytes(
            SpriteInputIndex::Sprites as u64,
            mem::size_of_val(&effect.transform) as u64,
            &effect.transform as *const TransformationMatrix as *const _,
        );
        command_encoder.set_vertex_bytes(
            SpriteInputIndex::ViewportSize as u64,
            mem::size_of_val(&viewport_size) as u64,
            &viewport_size as *const Size<DevicePixels> as *const _,
        );
        command_encoder.set_fragment_texture(SpriteInputIndex::AtlasTexture as u64, Some(pixels));
        command_encoder.set_fragment_bytes(
            SpriteInputIndex::AtlasTextureSize as u64,
            mem::size_of::<GroupComposite>() as u64,
            &composite as *const GroupComposite as *const _,
        );
        command_encoder.draw_primitives(metal::MTLPrimitiveType::Triangle, 0, 6);
        command_encoder.end_encoding();
    }

    fn draw_paths_to_intermediate(
        &self,
        paths: &[Path<ScaledPixels>],
        instance_buffer: &mut InstanceBuffer,
        instance_offset: &mut usize,
        viewport_size: Size<DevicePixels>,
        command_buffer: &metal::CommandBufferRef,
    ) -> bool {
        if paths.is_empty() {
            return true;
        }
        let Some(intermediate_texture) = &self.path_intermediate_texture else {
            return false;
        };

        let render_pass_descriptor = metal::RenderPassDescriptor::new();
        let color_attachment = render_pass_descriptor
            .color_attachments()
            .object_at(0)
            .unwrap();
        color_attachment.set_load_action(metal::MTLLoadAction::Clear);
        color_attachment.set_clear_color(metal::MTLClearColor::new(0., 0., 0., 0.));

        if let Some(msaa_texture) = &self.path_intermediate_msaa_texture {
            color_attachment.set_texture(Some(msaa_texture));
            color_attachment.set_resolve_texture(Some(intermediate_texture));
            color_attachment.set_store_action(metal::MTLStoreAction::MultisampleResolve);
        } else {
            color_attachment.set_texture(Some(intermediate_texture));
            color_attachment.set_store_action(metal::MTLStoreAction::Store);
        }

        let command_encoder = command_buffer.new_render_command_encoder(render_pass_descriptor);
        command_encoder.set_render_pipeline_state(&self.paths_rasterization_pipeline_state);

        align_offset(instance_offset);
        let mut vertices = Vec::new();
        for path in paths {
            vertices.extend(path.vertices.iter().map(|v| PathRasterizationVertex {
                xy_position: v.xy_position,
                st_position: v.st_position,
                color: path.color,
                bounds: path.bounds.intersect(&path.content_mask.bounds),
            }));
        }
        let vertices_bytes_len = mem::size_of_val(vertices.as_slice());
        let next_offset = *instance_offset + vertices_bytes_len;
        if next_offset > instance_buffer.size {
            command_encoder.end_encoding();
            return false;
        }
        command_encoder.set_vertex_buffer(
            PathRasterizationInputIndex::Vertices as u64,
            Some(&instance_buffer.metal_buffer),
            *instance_offset as u64,
        );
        command_encoder.set_vertex_bytes(
            PathRasterizationInputIndex::ViewportSize as u64,
            mem::size_of_val(&viewport_size) as u64,
            &viewport_size as *const Size<DevicePixels> as *const _,
        );
        command_encoder.set_fragment_buffer(
            PathRasterizationInputIndex::Vertices as u64,
            Some(&instance_buffer.metal_buffer),
            *instance_offset as u64,
        );
        let buffer_contents =
            unsafe { (instance_buffer.metal_buffer.contents() as *mut u8).add(*instance_offset) };
        unsafe {
            ptr::copy_nonoverlapping(
                vertices.as_ptr() as *const u8,
                buffer_contents,
                vertices_bytes_len,
            );
        }
        command_encoder.draw_primitives(
            metal::MTLPrimitiveType::Triangle,
            0,
            vertices.len() as u64,
        );
        *instance_offset = next_offset;

        command_encoder.end_encoding();
        true
    }

    fn draw_shadows(
        &self,
        shadows: &[Shadow],
        instance_buffer: &mut InstanceBuffer,
        instance_offset: &mut usize,
        viewport_size: Size<DevicePixels>,
        command_encoder: &metal::RenderCommandEncoderRef,
    ) -> bool {
        if shadows.is_empty() {
            return true;
        }
        align_offset(instance_offset);

        command_encoder.set_render_pipeline_state(&self.shadows_pipeline_state);
        command_encoder.set_vertex_buffer(
            ShadowInputIndex::Vertices as u64,
            Some(&self.unit_vertices),
            0,
        );
        command_encoder.set_vertex_buffer(
            ShadowInputIndex::Shadows as u64,
            Some(&instance_buffer.metal_buffer),
            *instance_offset as u64,
        );
        command_encoder.set_fragment_buffer(
            ShadowInputIndex::Shadows as u64,
            Some(&instance_buffer.metal_buffer),
            *instance_offset as u64,
        );

        command_encoder.set_vertex_bytes(
            ShadowInputIndex::ViewportSize as u64,
            mem::size_of_val(&viewport_size) as u64,
            &viewport_size as *const Size<DevicePixels> as *const _,
        );

        let shadow_bytes_len = mem::size_of_val(shadows);
        let buffer_contents =
            unsafe { (instance_buffer.metal_buffer.contents() as *mut u8).add(*instance_offset) };

        let next_offset = *instance_offset + shadow_bytes_len;
        if next_offset > instance_buffer.size {
            return false;
        }

        unsafe {
            ptr::copy_nonoverlapping(
                shadows.as_ptr() as *const u8,
                buffer_contents,
                shadow_bytes_len,
            );
        }

        command_encoder.draw_primitives_instanced(
            metal::MTLPrimitiveType::Triangle,
            0,
            6,
            shadows.len() as u64,
        );
        *instance_offset = next_offset;
        true
    }

